/* Orange Puma 60 by Bodyhc — https://uiverse.io/Bodyhc/orange-puma-60 */
button {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  border-radius: 20px;
  background-image: linear-gradient(
    90deg,
    #fa7fe6 0%,
    #ff8e61 50%,
    #fa7fe6 100%
  );
  border: 2px solid #9d098431;
  color: #000000;
  font-weight: 600;
  padding: 20px 40px;
  cursor: pointer;
}
button svg {
  font-size: 24px;
  margin-right: 10px;
  width: 30px;
  height: 20px;
  color: black;
}
button:hover {
  background-image: linear-gradient(
    90deg,
    #ff8e61 0%,
    #fa7fe6 50%,
    #fe9b74 100%
  );
}
